const workflows = [
  { id: 'S62o0wcXq8Wfj67S', nombre: 'Strategist AI v3.0', chequearLoop: false },
  { id: 'nHawWPIIu51ABBgl', nombre: 'Ideas AI', chequearLoop: false },
  { id: 'wyO1f93A66imn9qw', nombre: 'Content AI (RRSS v1.4)', chequearLoop: false },
  { id: '1rsqmFabW5PjnlHy', nombre: 'Image Generator AI', chequearLoop: false },
  { id: 'IRCoya91PKPjpT1T', nombre: 'Distribution AI', chequearLoop: false },
  { id: 'aMCwIQ3eY1bzyMyt', nombre: 'Distribution AI — Puente Temporal (2min)', chequearLoop: true },
  { id: '62tIvF0snsrMj0sM', nombre: 'Community AI', chequearLoop: true },
  { id: 'otycsrxrMEMuxuwD', nombre: 'Sales AI Motor', chequearLoop: true },
  { id: 'EX9K1AZwKeouSJ9G', nombre: 'Analytics AI Semanal', chequearLoop: false },
  { id: 'YI9EfJYcWJN4bbM9', nombre: 'Analytics AI Mensual (V3 Meta Reporte)', chequearLoop: false }
];
return workflows.map(w => ({ json: w }));

const listaItems = $('📋 Lista de Workflows RRSS').all();
const wfItems = $('🔎 n8n: GET Workflow').all();
const execItems = $('🔎 n8n: GET Ejecuciones').all();
const hallazgos = [];
const now = Date.now();

for (let i = 0; i < listaItems.length; i++) {
  const info = listaItems[i].json;
  const wf = wfItems[i].json;
  const ejecuciones = (execItems[i].json.data) || [];

  if (wf.active !== true) {
    hallazgos.push({
      tipo: 'workflow_inactivo',
      severidad: 'critico',
      clave: `inactivo_${info.id}`,
      mensaje: `El workflow "${info.nombre}" está DESACTIVADO en n8n y debería estar activo.`
    });
  }

  const recientes = ejecuciones.slice(0, 3);
  const todasFallidas = recientes.length > 0 && recientes.every(e => e.status === 'error');
  if (todasFallidas) {
    hallazgos.push({
      tipo: 'ejecuciones_fallidas',
      severidad: 'critico',
      clave: `fallas_${info.id}`,
      mensaje: `"${info.nombre}" — las últimas ${recientes.length} ejecuciones terminaron en error.`
    });
  }

  if (info.chequearLoop) {
    const quinceMinAtras = now - 15 * 60 * 1000;
    const recientesVolumen = ejecuciones.filter(e => {
      const t = new Date(e.startedAt).getTime();
      return !isNaN(t) && t >= quinceMinAtras;
    });
    if (recientesVolumen.length > 15) {
      hallazgos.push({
        tipo: 'volumen_anomalo',
        severidad: 'critico',
        clave: `loop_${info.id}`,
        mensaje: `"${info.nombre}" — ${recientesVolumen.length} ejecuciones en los últimos 15 minutos, posible loop (mismo patrón del incidente real del 14-jul en Community AI).`
      });
    }
  }
}

return [{ json: { hallazgos } }];

const G54 = 'https://api.growth54.com';
const MASTER_EMAIL = 'master@growth54.local';
const MASTER_PASSWORD = 'REDACTED_PASSWORD';
const hallazgos = ($input.first().json.hallazgos || []).slice();

try {
  const loginResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${G54}/api/auth/login`,
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: { email: MASTER_EMAIL, password: MASTER_PASSWORD },
    json: true
  });
  const token = loginResp.access_token;

  const companiesResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${G54}/api/n8n/companies`,
    headers: { Accept: 'application/json' },
    json: true
  });
  const empresas = (companiesResp.data || companiesResp || []).filter(e => e.is_active !== false && e.activo !== false);
  const ahora = Date.now();

  for (const empresa of empresas) {
    const empresaId = empresa.id || empresa.company_id;
    const empresaNombre = empresa.name || empresa.nombre || String(empresaId);
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${G54}/api/auth/switch-company`,
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Accept: 'application/json' },
        body: { company_id: empresaId },
        json: true
      });

      const postsResp = await this.helpers.httpRequest({
        method: 'GET',
        url: `${G54}/api/rrss/posts`,
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
        json: true
      });
      const posts = postsResp.data || postsResp || [];

      const atascados = posts.filter(p => {
        if (p.status !== 'programado' || !p.fecha_programada) return false;
        const fechaProg = new Date(p.fecha_programada).getTime();
        return !isNaN(fechaProg) && (ahora - fechaProg) > 15 * 60 * 1000;
      });

      if (atascados.length > 0) {
        const revertidos = [];
        const fallidos = [];
        for (const p of atascados) {
          try {
            await this.helpers.httpRequest({
              method: 'PUT',
              url: `${G54}/api/rrss/posts/${p.id}/status`,
              headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Accept: 'application/json' },
              body: { status: 'aprobado' },
              json: true
            });
            revertidos.push(p.id);
          } catch (revertErr) {
            fallidos.push(p.id);
          }
        }
        const detalle = revertidos.length ? ` Revertidos automáticamente a "aprobado" (vigía): ${revertidos.join(', ')}.` : '';
        const detalleFallo = fallidos.length ? ` No se pudo revertir: ${fallidos.join(', ')} (requiere revisión manual).` : '';
        hallazgos.push({
          tipo: 'posts_atascados',
          severidad: fallidos.length > 0 ? 'critico' : 'atencion',
          clave: `atascados_empresa_${empresaId}`,
          mensaje: `Empresa "${empresaNombre}" — ${atascados.length} post(s) en "programado" con fecha vencida hace más de 15 min (IDs: ${atascados.map(p => p.id).join(', ')}).${detalle}${detalleFallo}`,
          autoCorregido: fallidos.length === 0
        });
      }

      const porIdea = {};
      for (const p of posts) {
        if (!p.social_idea_id) continue;
        if (!porIdea[p.social_idea_id]) porIdea[p.social_idea_id] = [];
        porIdea[p.social_idea_id].push(p.id);
      }
      const duplicados = Object.entries(porIdea).filter(([, ids]) => ids.length > 1);
      if (duplicados.length > 0) {
        hallazgos.push({
          tipo: 'posts_duplicados',
          severidad: 'atencion',
          clave: `duplicados_empresa_${empresaId}`,
          mensaje: `Empresa "${empresaNombre}" — ${duplicados.length} idea(s) con más de un post generado (posible regresión del bug de duplicación de Content AI): ${duplicados.map(([ideaId, ids]) => `idea ${ideaId} → posts ${ids.join('/')}`).join('; ')}. Revisar manualmente cuál conservar — no se borra nada automáticamente.`
        });
      }

      try {
        const ideasResp = await this.helpers.httpRequest({
          method: 'GET',
          url: `${G54}/api/rrss/ideas`,
          headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
          json: true
        });
        const ideas = ideasResp.data || ideasResp || [];
        if (ideas.length > 0) {
          const masReciente = ideas.reduce((max, i) => {
            const t = new Date(i.created_at || i.fecha_propuesta || 0).getTime();
            return t > max ? t : max;
          }, 0);
          const diasSinIdeas = (ahora - masReciente) / (24 * 60 * 60 * 1000);
          if (diasSinIdeas > 8) {
            hallazgos.push({
              tipo: 'ideas_estancadas',
              severidad: 'atencion',
              clave: `ideas_estancadas_${empresaId}`,
              mensaje: `Empresa "${empresaNombre}" — la idea más reciente tiene ${Math.floor(diasSinIdeas)} días. El disparo semanal de Ideas AI puede estar roto para esta empresa.`
            });
          }
        }
      } catch (ideasErr) {
        // no bloquear el resto de chequeos por esto
      }

      if (String(empresaId) === '1') {
        const conImagen = posts.find(p => p.imagen_url);
        if (conImagen) {
          try {
            await this.helpers.httpRequest({ method: 'GET', url: conImagen.imagen_url, json: false, returnFullResponse: true });
          } catch (imgErr) {
            const status = imgErr.statusCode || (imgErr.response && imgErr.response.statusCode) || (imgErr.cause && imgErr.cause.statusCode);
            if (status === 404) {
              hallazgos.push({
                tipo: 'storage_404',
                severidad: 'atencion',
                clave: 'storage_404_ce',
                mensaje: `Regresión del 404 de storage de imágenes en G54 (post ${conImagen.id}, Crating Express) — mismo bug ya resuelto y vuelto a romper el 22-jul. No se puede auto-corregir, depende del servidor de Walter.`
              });
            }
          }
        }

        try {
          const waResp = await this.helpers.httpRequest({
            method: 'GET',
            url: `${G54}/api/whatsapp/config`,
            headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
            json: true
          });
          const waData = waResp.data || waResp;
          const prompt = waData && waData.system_prompt;
          if (!prompt || !prompt.includes('{{CATALOGO}}')) {
            hallazgos.push({
              tipo: 'wa_config_g54_invalido',
              severidad: 'atencion',
              clave: 'wa_config_ce',
              mensaje: 'GET /api/whatsapp/config para Crating Express no trae un system_prompt válido (esperaba el marcador {{CATALOGO}}). Marco cae a su fallback fijo automáticamente, sin downtime — pero conviene revisar por qué G54 dejó de servir el prompt real.'
            });
          }
        } catch (waErr) {
          hallazgos.push({
            tipo: 'wa_config_g54_error',
            severidad: 'atencion',
            clave: 'wa_config_ce_error',
            mensaje: `No se pudo leer /api/whatsapp/config para Crating Express: ${waErr.message || waErr}. Marco sigue funcionando con su fallback fijo mientras tanto.`
          });
        }
      }
    } catch (empresaErr) {
      hallazgos.push({
        tipo: 'g54_error_empresa',
        severidad: 'atencion',
        clave: `g54_error_${empresaId}`,
        mensaje: `No se pudo revisar la empresa "${empresaNombre}" en G54: ${empresaErr.message || empresaErr}`
      });
    }
  }
} catch (loginErr) {
  hallazgos.push({
    tipo: 'g54_login_fallo',
    severidad: 'critico',
    clave: 'g54_login_fallo',
    mensaje: `No se pudo iniciar sesión en G54 para revisar posts/storage: ${loginErr.message || loginErr}`
  });
}

return [{ json: { hallazgos } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.ultimaAlerta) staticData.ultimaAlerta = {};
const ahora = Date.now();
const COOLDOWN_MS = 6 * 60 * 60 * 1000;

const todos = $json.hallazgos || [];
const paraAlertar = [];

for (const h of todos) {
  const ultima = staticData.ultimaAlerta[h.clave];
  if (!ultima || (ahora - ultima) > COOLDOWN_MS) {
    paraAlertar.push(h);
    staticData.ultimaAlerta[h.clave] = ahora;
  }
}

return [{ json: { hallazgosParaAlertar: paraAlertar, totalCrudo: todos.length } }];

const hallazgos = $json.hallazgosParaAlertar;
const criticos = hallazgos.filter(h => h.severidad === 'critico');
const atencion = hallazgos.filter(h => h.severidad !== 'critico');

const fecha = new Date().toLocaleString('es-NI', { timeZone: 'America/Managua', dateStyle: 'medium', timeStyle: 'short' });

function filaTexto(h) {
  const label = h.severidad === 'critico' ? '[CRITICO]' : '[ATENCION]';
  let tag = '';
  if (h.autoCorregido === true) tag = ' (AUTO-CORREGIDO)';
  else if (h.autoCorregido === false) tag = ' (AUTO-FIX FALLO)';
  return `${label} ${h.tipo}${tag}\n${h.mensaje}\n`;
}

function filaHtml(h) {
  const color = h.severidad === 'critico' ? '#dc3545' : '#ffc107';
  const label = h.severidad === 'critico' ? 'CRITICO' : 'ATENCION';
  let autoTag = '';
  if (h.autoCorregido === true) autoTag = ' [AUTO-CORREGIDO]';
  else if (h.autoCorregido === false) autoTag = ' [AUTO-FIX FALLO]';
  return '<div style="border-left:4px solid ' + color + ';background:#f8f9fa;padding:12px 16px;margin:10px 0;border-radius:4px;">' +
    '<div style="font-size:11px;font-weight:bold;color:' + color + ';margin-bottom:4px;">' + label + ' — ' + h.tipo + autoTag + '</div>' +
    '<div style="font-size:14px;color:#333;">' + h.mensaje + '</div></div>';
}

let textoPlano = 'VIGIA G54 — Reporte de Hallazgos\n' + fecha + ' (hora Nicaragua)\n' + '='.repeat(50) + '\n\n';
if (criticos.length) { textoPlano += 'CRITICOS:\n\n' + criticos.map(filaTexto).join('\n'); }
if (atencion.length) { textoPlano += '\nATENCION:\n\n' + atencion.map(filaTexto).join('\n'); }
textoPlano += '\n' + '='.repeat(50) + '\nChequeo automatico cada 2 horas. Los marcados AUTO-CORREGIDO ya se aplicaron solos. Este hallazgo no se repite antes de 6 horas si el problema persiste sin cambios.';

const html = '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;color:#333;">' +
  '<div style="background:#1a1a2e;color:white;padding:20px;border-radius:8px 8px 0 0;">' +
  '<h1 style="margin:0;font-size:20px;">Vigia G54 — Reporte de Hallazgos</h1>' +
  '<p style="margin:5px 0 0;opacity:0.8;font-size:13px;">' + fecha + ' (hora Nicaragua)</p></div>' +
  '<div style="border:1px solid #ddd;padding:20px;border-top:none;">' +
  (criticos.length ? '<h3 style="color:#dc3545;">Criticos</h3>' + criticos.map(filaHtml).join('') : '') +
  (atencion.length ? '<h3 style="color:#856404;margin-top:16px;">Atencion</h3>' + atencion.map(filaHtml).join('') : '') +
  '<p style="margin-top:20px;font-size:12px;color:#999;">Chequeo automatico cada 2 horas. Los marcados AUTO-CORREGIDO ya se aplicaron solos. Este hallazgo no se repite antes de 6 horas si el problema persiste sin cambios.</p>' +
  '</div></div>';

const emoji = criticos.length ? '[!]' : '[i]';
const subject = emoji + ' Vigia G54 — ' + hallazgos.length + ' hallazgo(s) — ' + fecha;

return [{ json: { subject, html, textoPlano } }];

const N8N_BASE = "https://n8n.mdarthurdigital.com/api/v1";
const N8N_API_KEY = "REDACTED_N8N_API_KEY";
const hallazgos = ($input.first().json.hallazgos || []).map(h => ({...h}));
const authHeader = { "X-N8N-API-KEY": N8N_API_KEY };

for (const h of hallazgos) {
  if (h.tipo === "workflow_inactivo") {
    const workflowId = h.clave.replace("inactivo_", "");
    try {
      await this.helpers.httpRequest({
        method: "POST",
        url: `${N8N_BASE}/workflows/${workflowId}/activate`,
        headers: authHeader,
        json: true
      });
      h.mensaje += " -> Se reactivo automaticamente (vigia).";
      h.autoCorregido = true;
    } catch (e) {
      h.mensaje += ` -> Intento de reactivacion automatica fallo: ${e.message || e}. Requiere revision manual.`;
      h.autoCorregido = false;
    }
  }

  if (h.tipo === "volumen_anomalo") {
    const workflowId = h.clave.replace("loop_", "");
    try {
      await this.helpers.httpRequest({
        method: "POST",
        url: `${N8N_BASE}/workflows/${workflowId}/deactivate`,
        headers: authHeader,
        json: true
      });
      h.mensaje += " -> Se DESACTIVO automaticamente como freno de emergencia (vigia). Reactivar a mano una vez corregida la causa.";
      h.autoCorregido = true;
      h.severidad = "critico";
    } catch (e) {
      h.mensaje += ` -> Intento de desactivacion automatica fallo: ${e.message || e}. Apagarlo a mano YA.`;
      h.autoCorregido = false;
    }
  }
}

return [{ json: { hallazgos } }];

const hallazgos = ($('🔧 Ejecutar Auto-Correcciones').item.json.hallazgos || []).slice();
const groqResp = $json;
const groqError = groqResp.error;

if (groqError) {
  const status = groqResp.statusCode || (groqResp.cause && groqResp.cause.statusCode) || (typeof groqError === 'object' && groqError.httpCode);
  if (Number(status) === 429) {
    hallazgos.push({
      tipo: 'groq_cuota_agotada', severidad: 'atencion', clave: 'groq_cuota',
      mensaje: 'Groq devolvió 429 (cuota agotada) en el chequeo de salud del vigía — Marco y los agentes de contenido pueden estar degradando a Modo Contingencia / fallback en cualquier momento. No se puede auto-corregir (límite de cuenta compartida), solo avisar.'
    });
  } else if (Number(status) === 401) {
    hallazgos.push({
      tipo: 'groq_credencial_invalida', severidad: 'critico', clave: 'groq_401',
      mensaje: 'La credencial de Groq (jORffbRhRNohHT1B) parece inválida o revocada (401) — TODOS los agentes que dependen de Groq como IA primaria van a fallar. Revisar la API key cuanto antes.'
    });
  } else {
    hallazgos.push({
      tipo: 'groq_error_desconocido', severidad: 'atencion', clave: 'groq_error',
      mensaje: `Chequeo de salud de Groq devolvió un error inesperado: ${JSON.stringify(groqError).slice(0, 200)}`
    });
  }
}

return [{ json: { hallazgos } }];
